{
  "name": "@smthrs/platform-bun",
  "type": "module",
  "version": "1.0.0-rc.16",
  "license": "MIT",
  "smthrs": {
    "group": "engine",
    "privateEffectAdapters": [
      "@effect/platform-bun",
      "@effect/platform-node",
      "@effect/platform-node-shared"
    ]
  },
  "description": "Bun Host bundle for flows: Effect's Bun platform services composed into the closed Host surface",
  "homepage": "https://github.com/smithersai/smithers",
  "repository": {
    "type": "git",
    "url": "https://github.com/smithersai/smithers.git",
    "directory": "packages/smithers/flows/platform-bun"
  },
  "bugs": {
    "url": "https://github.com/smithersai/smithers/issues"
  },
  "tags": [
    "typescript",
    "effect",
    "bun",
    "platform"
  ],
  "keywords": [
    "typescript",
    "effect",
    "bun",
    "platform"
  ],
  "engines": {
    "bun": ">=1.4.0",
    "node": ">=22.19.0"
  },
  "sideEffects": [],
  "exports": {
    "./package.json": "./package.json",
    ".": "./src/index.ts",
    "./internal/*": null,
    "./*/index": null,
    "./BunFileSystem": "./src/BunFileSystem.ts",
    "./BunHost": "./src/BunHost.ts",
    "./index": "./src/index.ts"
  },
  "files": [
    "src/**/*.ts",
    "dist/**/*.js",
    "dist/**/*.js.map",
    "dist/**/*.d.ts",
    "dist/**/*.d.ts.map",
    "dist/**/package.json",
    "LICENSE",
    "README.md",
    "CHANGELOG.md",
    "dist/vendor/**",
    "docs/"
  ],
  "publishConfig": {
    "access": "public",
    "provenance": true,
    "tag": "next",
    "exports": {
      "./package.json": "./package.json",
      ".": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      },
      "./internal/*": null,
      "./*/index": null,
      "./BunFileSystem": {
        "import": {
          "types": "./dist/esm/BunFileSystem.d.ts",
          "default": "./dist/esm/BunFileSystem.js"
        },
        "require": {
          "types": "./dist/cjs/BunFileSystem.d.ts",
          "default": "./dist/cjs/BunFileSystem.js"
        }
      },
      "./BunHost": {
        "import": {
          "types": "./dist/esm/BunHost.d.ts",
          "default": "./dist/esm/BunHost.js"
        },
        "require": {
          "types": "./dist/cjs/BunHost.d.ts",
          "default": "./dist/cjs/BunHost.js"
        }
      },
      "./index": {
        "import": {
          "types": "./dist/esm/index.d.ts",
          "default": "./dist/esm/index.js"
        },
        "require": {
          "types": "./dist/cjs/index.d.ts",
          "default": "./dist/cjs/index.js"
        }
      }
    }
  },
  "scripts": {
    "lint": "eslint src --max-warnings=0 && dprint check",
    "format": "dprint fmt",
    "build": "node scripts/build.mjs",
    "check": "vibelang -b tsconfig.json && vibelang -p tsconfig.test.json --noEmit",
    "circular": "node ../../../repo-targets/scripts/circular.mjs",
    "test": "vitest",
    "coverage": "vitest --coverage"
  },
  "dependencies": {
    "@smthrs/database": "1.0.0-rc.16",
    "@smthrs/jj": "1.0.0-rc.16",
    "@smthrs/kernel": "1.0.0-rc.16",
    "@smthrs/sandbox": "1.0.0-rc.16",
    "@types/ws": "8.18.2",
    "redis": "6.2.1",
    "undici": "8.11.2",
    "ws": "8.22.0"
  },
  "peerDependencies": {
    "@smthrs/platform-node": "1.0.0-rc.16",
    "effect": "4.0.5"
  },
  "devDependencies": {
    "@effect/language-service": "0.87.2",
    "@effect/platform-bun": "4.0.5",
    "@effect/platform-node": "4.0.5",
    "@effect/platform-node-shared": "4.0.5",
    "@effect/sql-pg": "4.0.5",
    "@effect/vitest": "4.0.5",
    "@eslint/js": "9.39.5",
    "@smthrs/artifacts": "1.0.0-rc.16",
    "@smthrs/flows": "1.0.0-rc.16",
    "@smthrs/platform-node": "1.0.0-rc.16",
    "@types/node": "26.4.1",
    "@vitest/coverage-v8": "5.0.0",
    "dprint": "0.57.1",
    "effect": "4.0.5",
    "esbuild": "0.28.2",
    "eslint": "9.39.5",
    "eslint-import-resolver-typescript": "4.4.5",
    "eslint-plugin-import": "2.32.0",
    "eslint-plugin-jsdoc": "64.3.4",
    "eslint-plugin-unicorn": "65.0.0",
    "madge": "8.0.0",
    "typescript": "5.9.3",
    "typescript-eslint": "8.69.0",
    "vibelang": "0.0.8",
    "vibelang-vite": "0.0.8",
    "vitest": "5.0.0"
  }
}

import { mkdirSync, mkdtempSync, rmSync } from "node:fs"
import { join } from "node:path"
import { fileURLToPath } from "node:url"
import vibelang from "vibelang-vite"
import { configDefaults, defineConfig } from "vitest/config"

// Each Node runner owns a private report directory. Keep it until reporting has
// finished, including failed runs, then remove it when the runner exits.
const coverageRoot = join(import.meta.dirname, "coverage")
const reportsDirectory = process.versions.bun ? undefined : (() => {
  mkdirSync(coverageRoot, { recursive: true, mode: 0o700 })
  const directory = mkdtempSync(join(coverageRoot, "run-"))
  process.once("exit", () => rmSync(directory, { recursive: true, force: true }))
  return directory
})()

export default defineConfig({
  plugins: [vibelang({ project: "tsconfig.test.json" })],
  test: {
    globalSetup: [fileURLToPath(new URL("../../../repo-targets/test-utils/test-schemas.ts", import.meta.url))],
    include: [...configDefaults.include, "**/*.{test,spec}.vibe"],
    environment: "node",
    setupFiles: ["./test/BunRuntime.setup.ts"],
    // Like platform-node, these contracts exercise real filesystem operations,
    // child processes, jj, and loopback HTTP. The macOS runner exceeded
    // Vitest's 5 s default in the filesystem contract; retain the same finite
    // 30 s test and cleanup budgets used by the Node host suite.
    testTimeout: 30_000,
    hookTimeout: 30_000,
    coverage: {
      enabled: !process.versions.bun,
      // This directory is fresh; cleaning would recreate it with broader permissions.
      clean: false,
      provider: "v8",
      ...(reportsDirectory === undefined ? {} : { reportsDirectory }),
      include: ["src/**/*.{ts,vibe}"],
      thresholds: { branches: 100, functions: 100, lines: 100, statements: 100 }
    }
  }
})
